// The keyboard's icons: the layouts name them by role (shift_key, enter_key, ...), the keyboard's Material You theme
// gives each role its drawable (icondata.js, generated by tools/vd2js.py --latinime).
import {paintIconData} from '../icons.js';
import {ICONS} from './icondata.js';

const BY_ROLE = {
    shift_key: 'sym_keyboard_shift',
    shift_key_shifted: 'sym_keyboard_shift_locked',
    delete_key: 'sym_keyboard_delete',
    settings_key: 'sym_keyboard_settings',
    space_key: null,
    space_key_for_number_layout: 'sym_keyboard_space',
    enter_key: 'sym_keyboard_return',
    go_key: 'sym_keyboard_next',
    search_key: 'sym_keyboard_search',
    send_key: 'sym_keyboard_send',
    next_key: 'sym_keyboard_next',
    done_key: 'sym_keyboard_done',
    previous_key: 'sym_keyboard_previous',
    tab_key: 'sym_keyboard_tab',
    shortcut_key: 'sym_keyboard_voice',
    shortcut_key_disabled: 'sym_keyboard_voice_off',
    language_switch_key: 'sym_keyboard_language_switch',
    emoji_action_key: 'sym_keyboard_smiley',
    emoji_normal_key: 'sym_keyboard_smiley',
    clipboard_paste_key: 'sym_keyboard_clipboard_paste',
    // the suggestion strip's and the navigation bar's
    float_key: 'ic_floating_keyboard',
    split_key: 'ic_split_keyboard',
    nav_hide: 'ic_ime_nav_back',
    nav_switcher: 'ic_ime_switcher',
};

export function iconFor(role) {
    const name = BY_ROLE[role];
    return name ? ICONS[name] ?? null : null;
}

// Paint the icon of @role into the box (x, y, w, h) of @cr's user space, its viewport stretched to the box as a
// drawable's bounds stretch it, in @color at @alpha
export function paintKeyIcon(cr, role, x, y, w, h, color, alpha = 1) {
    const icon = iconFor(role);
    if (!icon)
        return;
    cr.save();
    cr.translate(x, y);
    cr.scale(w / icon.w, h / icon.h);
    // every viewport here is square: painted at its own size, it fills the box
    paintIconData(cr, icon, 0, 0, Math.max(icon.w, icon.h), color, alpha);
    cr.restore();
}
